(()=>{const buttons=[...document.querySelectorAll('[data-device]')];buttons.forEach(b=>b.addEventListener('click',()=>{const mode=b.dataset.device;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.body.classList.toggle('mobile-previews',mode==='mobile');document.querySelectorAll('.concept-preview').forEach(i=>{i.src=`/design/previews/${i.dataset.slug}-${mode}.png`;i.alt=i.alt.replace(/desktop|mobile/,mode);});}));})();
